public static function parseFromLocale($time, $locale = null, $tz = null)
{
    return static::rawParse(static::translateTimeString($time, $locale, 'en'), $tz);
}

/**
 * Get a Carbon instance for the current date and time.
 *
 * @param DateTimeZone|string|null $tz
 *
 * @return static
 */
public static function now($tz = null)
{
    return new static(null, $tz);
}

/**
 * Create a Carbon instance for today.
 *
 * @param DateTimeZone|string|null $tz
 *
 * @return static
 */
public static function today($tz = null)
{
    return static::rawParse('today', $tz);
}

/**
 * Create a Carbon instance for tomorrow.
 *
 * @param DateTimeZone|string|null $tz
 *
 * @return static
 */
 * If any of $year, $month or $day are set to null their now() values will
 * be used.
 *
 * If $hour is null it will be set to its now() value and the default
 * values for $minute and $second will be their now() values.
 *
 * If $hour is not null then the default values for $minute and $second
 * will be 0.
 *
 * @param DateTimeInterface|int|null $year
 * @param int|null                   $month
 * @param int|null                   $day
 * @param int|null                   $hour
 * @param int|null                   $minute
 * @param int|null                   $second
 * @param DateTimeZone|string|null   $tz
 *
 * @throws InvalidFormatException
 *
 * @return static|false
 */
public static function create($year = 0, $month = 1, $day = 1, $hour = 0, $minute = 0, $second = 0, $tz = null)
{
    if ((\is_string($year) && !is_numeric($year)) || $year instanceof DateTimeInterface) {
        return static::parse($year, $tz ?: (\is_string($month) || $month instanceof DateTimeZone ? $month : null));
    }

    $defaults = null;
    $getDefault = function ($unit) use ($tz, &$defaults) {
        if ($defaults === null) {
            $now = (new FactoryImmutable([], static::class))->createNowInstance($tz);

            $defaults = array_combine([
                'year',
                'month',
                'day',
                'hour',
                'minute',
                'second',
            ], explode('-', $now->rawFormat('Y-n-j-G-i-s.u')));
        }

        return $defaults[$unit];
    };

    $year = $year ?? $getDefault('year');
    $month = $month ?? $getDefault('month');
    $day = $day ?? $getDefault('day');
    $hour = $hour ?? $getDefault('hour');
    $minute = $minute ?? $getDefault('minute');
    $second = (float) ($second ?? $getDefault('second'));
{
    Carbon::setToStringFormat(function (CarbonInterface $d) {
        $format = $d->year === 1976 ?
            'jS \o\f F g:i:s a' :
            'jS \o\f F, Y g:i:s a';

        return $d->format($format);
    });

    $d = Carbon::create(1976, 12, 25, 14, 15, 16);
    $this->assertSame('25th of December 2:15:16 pm', ''.$d);

    $d = Carbon::create(1975, 12, 25, 14, 15, 16);
    $this->assertSame('25th of December, 1975 2:15:16 pm', ''.$d);
}

public function testSetToStringFormatViaSettings()
{
    $factory = new FactoryImmutable([
        'toStringFormat' => function (CarbonInterface $d) {
            return $d->isoFormat('dddd');
        },
    ]);

    $d = $factory->create(1976, 12, 25, 14, 15, 16);
    $this->assertSame('Saturday', ''.$d);
}

public function testResetToStringFormat()
{
